let prefix = '${computer_prefix}';
let online = toscalar(Heartbeat | where Computer startswith prefix | summarize dcountif(Computer, TimeGenerated > ago(10m)));
let total = toscalar(Heartbeat | where Computer startswith prefix | summarize dcount(Computer));
let bootFail = toscalar(Syslog | where TimeGenerated > ago(24h) | where Facility == 'local0' | where SyslogMessage has_cs 'ERROR' or SyslogMessage has_cs 'FATAL' or SyslogMessage has 'still failing after' | summarize dcount(Computer));
let diskHot = toscalar(Perf | where Computer startswith prefix | where ObjectName == 'Logical Disk' and CounterName == '% Used Space' | where InstanceName !startswith '/snap' and InstanceName !in ('_Total', '/boot/efi') | summarize arg_max(TimeGenerated, CounterValue) by Computer, InstanceName | summarize countif(CounterValue >= toreal('{DiskWarn}')));
let sysErr = toscalar(Syslog | where TimeGenerated > ago(24h) | where Computer startswith prefix | where SeverityLevel in ('err','error','crit','alert','emerg') | count);
union
(print Metric = 'Runners online', Value = strcat(tostring(online), ' / ', tostring(total)), o = 1),
(print Metric = 'Bootstrap failures (24h)', Value = tostring(bootFail), o = 2),
(print Metric = 'Disk mounts at/over warn', Value = tostring(diskHot), o = 3),
(print Metric = 'OS errors (24h)', Value = tostring(sysErr), o = 4)
| sort by o asc | project Metric, Value

let prefix = '${computer_prefix}';
let hb = Heartbeat | where Computer startswith prefix | summarize LastHeartbeat = max(TimeGenerated) by Computer;
let perf = Perf | where Computer startswith prefix | where TimeGenerated > ago(15m)
  | summarize CPU_pct = round(avgif(CounterValue, ObjectName == 'Processor' and CounterName == '% Processor Time'), 1),
              Mem_used_pct = round(avgif(CounterValue, ObjectName == 'Memory' and CounterName == '% Used Memory'), 1),
              Disk_used_pct = round(maxif(CounterValue, ObjectName == 'Logical Disk' and CounterName == '% Used Space' and InstanceName !startswith '/snap' and InstanceName !in ('_Total', '/boot/efi')), 1)
    by Computer;
hb | join kind=leftouter perf on Computer
| extend Status = iff(LastHeartbeat > ago(10m), 'Online', 'Stale')
| project Computer, Status, LastHeartbeat, CPU_pct, Mem_used_pct, Disk_used_pct
| sort by Computer asc

let prefix = '${computer_prefix}';
let done = Syslog | where Facility == 'local0' and SyslogMessage has 'Bootstrap complete' | distinct Computer;
Heartbeat | where Computer startswith prefix | summarize LastSeen = max(TimeGenerated) by Computer
| where Computer !in (done)
| extend Note = 'Instance is up and the agent reports, but bootstrap never logged completion'
| project Computer, LastSeen, Note | sort by LastSeen desc
